package org.blogs.Blogs.controller;import lombok.Data;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;import java.util.Map;@RestController@RequestMapping("/actuator")@Datapublic class HealthController {    @GetMapping("/health")    public ResponseEntity<Map<String, String>> health() {        return ResponseEntity.ok(                Map.of(                        "status", "UP",                        "message", "Application is running" +                                "I happy to see it is Up"                )        );    }}